import { expect, it } from 'vitest';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { validatePrintArtifacts } from './printArtifacts';
// Opt-in real-WASM fixture, generated by print-submission-smoke.mjs; never a physical print.
const directory = process.env.NEO_PRINT_FIXTURE_DIR;
it.skipIf(!directory)('accepts actual native dispatch archives and rejects different material identities', async () => {
  const root = directory!;
  const manifest = JSON.parse(await readFile(join(root, 'manifest.json'), 'utf8'));
  await expect(validatePrintArtifacts(join(root, 'print.3mf'), join(root, 'configuration.3mf'), manifest)).resolves.toBeUndefined();
  manifest.materials[0].index = 47;
  await expect(validatePrintArtifacts(join(root, 'print.3mf'), join(root, 'configuration.3mf'), manifest)).rejects.toThrow('material identities');
  await expect(validatePrintArtifacts(join(root, 'configuration.3mf'), join(root, 'print.3mf'), manifest)).rejects.toThrow('Invalid print archive');
});
